contracts/AgentPayEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AgentPayEscrow
 * @dev AgentPay 核心交易路由与担保合约（部署在 Base 链）
 * 实现 AI Agent 之间的“一手交钱、一手交接口”，并提取固定比例的协议费。
 */
interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract AgentPayEscrow {
    IERC20 public immutable settlementToken; // 结算代币（如 USDC）
    address public treasury;                 // 平台国库地址

    uint256 public feeBasisPoints = 250;     // 协议抽水：2.5% (250 / 10000)
    uint256 public constant DENOMINATOR = 10000;

    // 记录每笔交易的任务状态
    struct Task {
        address buyer;
        address seller;
        uint256 totalAmount;
        bool isCompleted;
    }

    mapping(bytes32 => Task) public tasks;

    // 事件：用于被链下 SDK 监听
    event TaskCreated(bytes32 indexed taskId, address indexed buyer, address indexed seller, uint256 amount);
    event TaskCompleted(bytes32 indexed taskId, address indexed seller, uint256 sellerAmount, uint256 feeAmount);

    /**
     * @param _settlementToken USDC在Base链上的合约地址
     * @param _treasury 咱们平台的国库钱包地址，用来装那 2.5% 的利润
     */
    constructor(address _settlementToken, address _treasury) {
        settlementToken = IERC20(_settlementToken);
        treasury = _treasury;
    }

    /**
     * @dev Step 1: 买方 Agent 发起任务并锁仓资金
     * @param taskId 唯一任务ID（可由买卖双方通过 Hash(交易内容) 生成）
     * @param seller 卖方 Agent 的钱包地址
     * @param amount 支付额度 (如 2 USDC = 2 * 10^6)
     */
    function lockFunds(bytes32 taskId, address seller, uint256 amount) external {
        require(tasks[taskId].buyer == address(0), "Task already exists");
        require(amount > 0, "Amount must be greater than 0");

        // 将买方的 USDC 扣除并锁入本合约
        // Note: 买方 Wallet 需提前 Approve 给本合约
        require(settlementToken.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        tasks[taskId] = Task({
            buyer: msg.sender,
            seller: seller,
            totalAmount: amount,
            isCompleted: false
        });

        emit TaskCreated(taskId, msg.sender, seller, amount);
    }

    /**
     * @dev Step 2: 买方 Agent 验证到数据后，触发放款 (或者平台充当 Oracle 触发)
     * @param taskId 唯一任务ID
     */
    function releaseFunds(bytes32 taskId) external {
        Task storage task = tasks[taskId];
        require(task.buyer != address(0), "Task does not exist");
        require(!task.isCompleted, "Task already completed");
        require(msg.sender == task.buyer, "Only buyer can release funds"); // 极简MVP：由买方确认收货

        task.isCompleted = true;

        // 计算抽成
        uint256 feeAmount = (task.totalAmount * feeBasisPoints) / DENOMINATOR;
        uint256 sellerAmount = task.totalAmount - feeAmount;

        // 瞬间打给卖方 97.5%
        require(settlementToken.transfer(task.seller, sellerAmount), "Transfer to seller failed");

        // 抽水进入国库 2.5%
        if (feeAmount > 0) {
            require(settlementToken.transfer(treasury, feeAmount), "Transfer to treasury failed");
        }

        emit TaskCompleted(taskId, task.seller, sellerAmount, feeAmount);
    }
}

contracts/AgentSmartWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AgentSmartWallet
 * @dev 挂载在人类老板名下的“智能体专属钱包”。
 * 利用会话密钥（Session Key）技术，让写在 Python 脚本里的 AI 凭临时私钥可以直接免密转账。
 * 但是通过合约底层的**每日消费限额（Daily Limit）**物理锁死，防止 AI 暴走。
 */
contract AgentSmartWallet {
    address public humanOwner;      // 人类老板的 MetaMask
    address public agentSessionKey; // 发给小弟 AI 的临时操作私钥对应的公钥

    uint256 public dailyLimit;      // 每日最大消耗额度 (如 10 USDC)
    uint256 public spentToday;      // 今天花进去的钱
    uint256 public lastResetTime;   // 上次重置限额的时间戳

    modifier onlyOwner() {
        require(msg.sender == humanOwner, "Only Human Owner!");
        _;
    }

    constructor(address _humanOwner) {
        humanOwner = _humanOwner;
        lastResetTime = block.timestamp;
    }

    /**
     * @dev 人类老板赋予 AI（代码）执行权限和额度
     * @param _sessionKey Python 脚本中 AI 持有的临时私钥对应的地址
     * @param _dailyLimit 每天的预算
     */
    function issueSessionKey(address _sessionKey, uint256 _dailyLimit) external onlyOwner {
        agentSessionKey = _sessionKey;
        dailyLimit = _dailyLimit;
    }

    /**
     * @dev AI 代码（或代理合约）调用此方法替自己花钱
     * @param target 目标购买的合约地址（比如 Escrow 担保合约）
     * @param data 调用该合约的哈希数据（包含要买什么、向谁买）
     * @param amount 涉及的支付金额（用于额度风控）
     */
    function executeAsAgent(address target, bytes calldata data, uint256 amount) external {
        // 1. 权限校验：这笔调用必须是由该 Session Key 签名的
        require(msg.sender == agentSessionKey, "Invalid Session Key");

        // 2. 额度恢复逻辑：过晚上12点，重新刷新 AI 带薪预算
        if (block.timestamp >= lastResetTime + 1 days) {
            spentToday = 0;
            lastResetTime = block.timestamp;
        }

        // 3. 防跑飞物理锁死 (非常硬核的规则)
        require(spentToday + amount <= dailyLimit, "Agent exceeded daily limit! Boss is angry.");

        // 4. 更新消耗，执行购买！(在 Base 链直接打向买入合约)
        spentToday += amount;

        (bool success, bytes memory result) = target.call(data);
        require(success, string(result));
    }

    /**
     * @dev 提现操作：万一不想让 AI 干了，老板随时直接把所有余额掏空
     */
    function emergencyWithdraw() external onlyOwner {
        // 逻辑略，把里面存放的 ETH 或 USDC 强行抽出到 humanOwner 账户中
    }
}

contracts/MockUSDC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

// 这是一个用于本地测试的模拟 USDC 合约
contract MockUSDC is ERC20 {
    constructor() ERC20("Mock USDC", "USDC") {}

    function mint(address to, uint256 amount) public {
        _mint(to, amount);
    }

    // USDC 的精度是 6
    function decimals() public view virtual override returns (uint8) {
        return 6;
    }
}

